// One item per recent video (uploads playlist = 'UU' + channel id)
const cfg = $('Config').first().json;
const cutoff = Date.now() - cfg.lookback_days * 86400000;
const out = [];
for (const item of $input.all()) {
  for (const v of (item.json.items || [])) {
    const published = v.contentDetails?.videoPublishedAt || v.snippet?.publishedAt;
    if (published && new Date(published).getTime() < cutoff) continue;
    out.push({ json: {
      video_id: v.contentDetails?.videoId || v.snippet?.resourceId?.videoId,
      title: v.snippet?.title || '',
      published_at: published
    }});
  }
}
return out;

// Normalise YouTube comment threads -> common comment shape
const videos = $('Split YouTube Videos').all().map(i => i.json);
const titleById = Object.fromEntries(videos.map(v => [v.video_id, v.title]));
const out = [];
for (const item of $input.all()) {
  for (const t of (item.json.items || [])) {
    const s = t.snippet?.topLevelComment?.snippet || {};
    const videoId = t.snippet?.videoId || s.videoId;
    out.push({ json: {
      platform: 'youtube',
      comment_id: t.id,
      text: s.textOriginal || s.textDisplay || '',
      likes: Number(s.likeCount) || 0,
      replies: Number(t.snippet?.totalReplyCount) || 0,
      author: s.authorDisplayName || '',
      posted_at: s.publishedAt || '',
      source_title: titleById[videoId] || '',
      source_url: `https://www.youtube.com/watch?v=${videoId}&lc=${t.id}`
    }});
  }
}
return out;

// One item per recent post that actually has comments
const cfg = $('Config').first().json;
const cutoff = Date.now() - cfg.lookback_days * 86400000;
const out = [];
for (const item of $input.all()) {
  for (const m of (item.json.data || [])) {
    if (!m.comments_count) continue;
    if (m.timestamp && new Date(m.timestamp).getTime() < cutoff) continue;
    out.push({ json: {
      media_id: m.id,
      caption: (m.caption || '').split('\n')[0].slice(0, 120),
      permalink: m.permalink,
      media_type: m.media_type
    }});
  }
}
return out;

// Normalise Instagram comments -> common comment shape (items are paired by index)
const posts = $('Split Instagram Posts').all().map(i => i.json);
const out = [];
$input.all().forEach((item, idx) => {
  const post = posts[idx] || {};
  for (const c of (item.json.data || [])) {
    out.push({ json: {
      platform: 'instagram',
      comment_id: c.id,
      text: c.text || '',
      likes: Number(c.like_count) || 0,
      replies: 0,
      author: c.username || '',
      posted_at: c.timestamp || '',
      source_title: post.caption || '',
      source_url: post.permalink || ''
    }});
  }
});
return out;

// Keep real questions/requests, drop spam & duplicates, build one prompt block
const all = $input.all().map(i => i.json).filter(c => c && c.text);

const QUESTION = /\?|^(how|what|why|when|where|which|who|can|could|should|would|is|are|does|do|will|any)\b/i;
const REQUEST = /(please make|pls make|make a video|can you (show|explain|make|do)|tutorial on|part 2|next video|would love (a|to see)|do a video|explain|cover)/i;
const SPAM = /(https?:\/\/|www\.|whatsapp|telegram me|dm me|check my|follow me|sub4sub|crypto|forex|investment advice|\+\d{8,})/i;

const seen = new Set();
const signal = [], other = [];
for (const c of all) {
  const text = c.text.replace(/\s+/g, ' ').trim();
  if (text.length < 12 || SPAM.test(text)) continue;
  if (!/[a-z]/i.test(text)) continue; // emoji-only
  const key = text.toLowerCase().replace(/[^a-z0-9 ]/g, '').slice(0, 80);
  if (seen.has(key)) continue;
  seen.add(key);
  const clean = { ...c, text: text.slice(0, 300) };
  (QUESTION.test(text) || REQUEST.test(text) ? signal : other).push(clean);
}

const byEngagement = (a, b) => (b.likes + b.replies * 2) - (a.likes + a.replies * 2);
signal.sort(byEngagement); other.sort(byEngagement);
// Pad with top-liked non-questions if the signal set is thin
const selected = signal.slice(0, 350).concat(signal.length < 40 ? other.slice(0, 40 - signal.length) : []);
selected.forEach((c, i) => { c.ref = 'C' + (i + 1); });

const prompt_block = selected
  .map(c => `[${c.ref}] (${c.platform}, ${c.likes} likes) ${c.text}`)
  .join('\n');

return [{ json: {
  total_collected: all.length,
  youtube_count: all.filter(c => c.platform === 'youtube').length,
  instagram_count: all.filter(c => c.platform === 'instagram').length,
  questions_found: signal.length,
  analysed_count: selected.length,
  comments: selected,
  prompt_block: prompt_block || 'NO COMMENTS FOUND'
}}];

