const raw = $json.message?.content ?? $json.content ?? $json.text ?? '';
let parsed = raw;
if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  try { parsed = JSON.parse(cleaned); } catch (err) { parsed = { __parse_error: cleaned.slice(0, 300) }; }
}

// Attach real counts/likes from the source comments and rank clusters by demand
const data = $('Clean & Filter Comments').first().json;
const byRef = Object.fromEntries(data.comments.map(c => [c.ref, c]));
const clusters = (parsed.clusters || []).map(cl => {
  const comments = (cl.comment_refs || []).map(r => byRef[r]).filter(Boolean);
  const likes = comments.reduce((s, c) => s + c.likes, 0);
  const platforms = [...new Set(comments.map(c => c.platform))];
  return {
    ...cl,
    mention_count: comments.length,
    total_likes: likes,
    platforms,
    demand_score: comments.length * 3 + likes * 0.5 + (platforms.length > 1 ? 5 : 0),
    sample_comments: comments.slice(0, 3).map(c => c.text),
    source_links: comments.slice(0, 3).map(c => c.source_url)
  };
}).filter(c => c.mention_count > 0).sort((a, b) => b.demand_score - a.demand_score);

// Next Monday as calendar start
const now = new Date();
const addDays = ((8 - now.getDay()) % 7) || 7;
const monday = new Date(now.getFullYear(), now.getMonth(), now.getDate() + addDays);
const iso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

return [{ json: {
  week_start: iso(monday),
  stats: { total: data.total_collected, youtube: data.youtube_count, instagram: data.instagram_count, questions: data.questions_found },
  clusters,
  emerging_topics: parsed.emerging_topics || [],
  cluster_error: parsed.__parse_error || ''
}}];

