const raw = $json.message?.content ?? $json.content ?? $json.text ?? '';
let parsed = raw;
if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  try { parsed = JSON.parse(cleaned); } catch (err) { parsed = { __parse_error: cleaned.slice(0, 300) }; }
}

const scored = $('Score Clusters').first().json;
const byId = Object.fromEntries(scored.clusters.map(c => [c.cluster_id, c]));
const entries = Array.isArray(parsed.entries) ? parsed.entries : [];
if (!entries.length) {
  return [{ json: { 'Week Of': scored.week_start, 'Title': 'Calendar generation failed — check AI output', 'Status': 'Error', 'Notes': parsed.__parse_error || '' } }];
}
return entries.map(e => {
  const ids = e.cluster_ids || [];
  return { json: {
    'Week Of': scored.week_start,
    'Week Theme': parsed.week_theme || '',
    'Date': e.date,
    'Day': e.day,
    'Platform': e.platform,
    'Format': e.format,
    'Title': e.title,
    'Hook': e.hook,
    'Outline': (e.outline || []).map((b, i) => `${i + 1}. ${b}`).join('\n'),
    'CTA': e.cta,
    'Questions Answered': (e.questions_answered || []).join(' | '),
    'Cluster IDs': ids.join(', '),
    'Audience Demand (mentions)': ids.reduce((s, id) => s + (byId[id]?.mention_count || 0), 0),
    'Priority': e.priority,
    'Effort': e.est_effort,
    'Status': 'Planned',
    'Backup Ideas': (parsed.backup_ideas || []).join(' | ')
  }};
});

// Collapse all calendar rows into one Slack message
const rows = $('Parse Calendar').all().map(i => i.json);
const s = $('Score Clusters').first().json;
const top = s.clusters.slice(0, 5)
  .map((c, i) => `${i + 1}. *${c.representative_question}* — ${c.mention_count} mentions, ${c.total_likes} likes (${c.platforms.join('+')})`)
  .join('\n');
const plan = rows
  .map(r => `• *${r.Day} ${r.Date}* · ${r.Platform}/${r.Format} · ${r.Title}${r.Priority === 'high' ? ' :fire:' : ''}`)
  .join('\n');
const text = [
  `:calendar: *Content calendar for week of ${s.week_start}*${rows[0]?.['Week Theme'] ? ' — _' + rows[0]['Week Theme'] + '_' : ''}`,
  `Scanned ${s.stats.total} comments (YT ${s.stats.youtube} · IG ${s.stats.instagram}), ${s.stats.questions} questions/requests, ${s.clusters.length} clusters.`,
  '', ':speech_balloon: *Top audience questions*', top || '_none found_',
  '', ':clapper: *Planned content*', plan,
  s.emerging_topics.length ? '\n:seedling: *Emerging:* ' + s.emerging_topics.slice(0, 5).join(' · ') : ''
].join('\n');
return [{ json: { text } }];
